def total_cost(node):
    if node is None:
        return 0
    child_total = 0
    for child in node.children:
        child_total += total_cost(child)
    return node.cost + child_total

def height(node):
    if node is None:
        return 0
    left_h = height(node.left)
    right_h = height(node.right)
    return 1 + max(left_h, right_h)
